INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 19, 'theory', 'Quiz: pipelining and performance');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 19, 0, 'How many cycles does an ideal 5-stage pipeline need for 100 instructions?', '["500", "104", "100", "5"]', 1, '5 + 100 − 1 = 104 cycles: the first instruction comes out after 5 cycles, and then one more every cycle.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 19, 1, 'What is forwarding (bypassing)?', '["Skipping an instruction at a branch", "Passing the ALU result straight to the input of the next instruction without waiting for the register write", "Copying the cache", "Branch prediction"]', 1, 'Forwarding removes stalls on data dependencies between arithmetic instructions.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 19, 2, 'Why is there still a stall after a load instruction (LW) even with forwarding?', '["A load is the longest instruction", "Data from memory is known only after the MEM stage, which is later than the ALU result", "The registers are busy", "The cache is off"]', 1, 'A load-use hazard costs one cycle; the compiler fills the gap with an independent instruction.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 19, 3, 'What does Amdahl''s law show?', '["Speeding up part of a program is limited by the share of the remaining time", "Moore''s law", "The number of transistors doubles", "Frequency cannot be raised"]', 0, 'Even if you speed up 90% of a program infinitely, you still get no more than 10×.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 19, 4, 'Why can''t processors be compared by MIPS and clock frequency?', '["These values are always the same", "Different processors spend a different number of instructions and cycles on the same task", "MIPS can only be measured on ARM", "Frequency does not affect speed"]', 1, 'A fair comparison is by the running time of real programs.');
